import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.CachePut;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

@Service
class ProductQueryService {

    // Kiem tra cache truoc; neu co du lieu thi BO QUA khong goi method.
    @Cacheable(value = "products", key = "#id", unless = "#result == null")
    public ProductDTO findById(Long id) {
        return loadFromDatabase(id);
    }

    // LUON goi method, roi cap nhat ket qua vao cache - dung khi ghi du lieu.
    @CachePut(value = "products", key = "#result.id")
    public ProductDTO update(ProductDTO updated) {
        return saveToDatabase(updated);
    }

    // Xoa toan bo entry trong cache "products" khi can lam moi hang loat.
    @CacheEvict(value = "products", allEntries = true)
    public void evictAllProducts() {
        // Spring xoa cache SAU KHI method chay xong; khong can code them trong body.
    }

    // Mo phong truy van DB that (vi du repository.findById(id)): tra ve gia tri THAT neu
    // id hop le, tra ve null neu khong tim thay - de CA HAI nhanh cua "unless" o @Cacheable
    // phia tren deu co the xay ra (id hop le duoc cache, id khong ton tai thi khong bi cache).
    private ProductDTO loadFromDatabase(Long id) {
        // Kho du lieu demo chi co product id tu 1 den 1_000.
        if (id == null || id <= 0 || id > 1_000) {
            return null;
        }
        return new ProductDTO(id, "San pham #" + id);
    }

    private ProductDTO saveToDatabase(ProductDTO dto) { return dto; }

    record ProductDTO(Long id, String name) {}
}

import java.time.Duration;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.cache.RedisCacheManager;
import org.springframework.data.redis.connection.RedisConnectionFactory;

@Configuration
@EnableCaching
class CacheConfig {

    @Bean
    public RedisCacheManager cacheManager(RedisConnectionFactory factory) {
        RedisCacheConfiguration defaults = RedisCacheConfiguration.defaultCacheConfig()
                .entryTtl(Duration.ofMinutes(10))   // TTL: het han 10 phut sau lan ghi/cap nhat gan nhat
                .disableCachingNullValues();          // khong cache gia tri null

        return RedisCacheManager.builder(factory)
                .cacheDefaults(defaults)
                .transactionAware()
                .build();
    }
}

import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.Async;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.stereotype.Service;

@Configuration
@EnableAsync
class AsyncConfig {
    // Chi can khai bao MOT LAN trong toan app: bat co che @Async cho moi bean co method @Async.
}

@Service
class ActivityLogService {

    // "Ban va quen": request goi method nay se KHONG cho no chay xong roi moi tra ve.
    // Neu than method nem exception, LUONG GOI khong the nhan loi qua return value; Spring mac dinh
    // se log loi, con handler tuy chinh o vi du sau cho phep xu ly/log tap trung.
    @Async
    public void recordActivity(String actorId, String action) {
        // Vi du best-effort: ghi mot activity log khong quyet dinh ket qua request.
        // Ban ghi audit bat buoc khong duoc mat khi app restart phai qua DB/queue ben vung,
        // khong chi dua vao @Async.
        System.out.println("[activity] " + actorId + " -> " + action);
    }
}

import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
class ProductEnrichmentService {

    private final ProductRepository productRepository;

    ProductEnrichmentService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    // CompletableFuture giu duoc CA ket qua va loi - khac voi vi du "ban va quen" (tra ve void) o tren.
    // (Gia dinh @EnableAsync da duoc khai bao mot lan trong app - xem vi du dau tien cua muc nay.)
    //
    // SAI (khong lam the nay): truyen thang mot entity JPA dang duoc quan ly boi persistence
    // context cua THREAD GOI. Worker @Async khong ke thua context do, nen khong duoc coi entity
    // la managed trong worker; khi transaction caller dong, entity co the thanh detached. Truy cap
    // lazy hoac thay doi cung mot entity qua hai thread deu khong an toan.
    //
    // DUNG: chi truyen id (gia tri bat bien, an toan giua cac thread), roi TAI LAI entity
    // ben trong chinh thread @Async, trong transaction rieng cua no.
    @Async
    @Transactional // transaction moi bat dau trong thread @Async, khong ke thua transaction cua caller
    public CompletableFuture<String> summarize(Long productId) {
        ProductEntity product = productRepository.findById(productId)
                .orElseThrow(() -> new IllegalStateException("Khong tim thay product " + productId));
        return CompletableFuture.completedFuture("Product #" + product.getId() + ": " + product.getName());
    }

    interface ProductRepository {
        Optional<ProductEntity> findById(Long id);
    }

    static class ProductEntity {
        private final Long id;
        private final String name;

        ProductEntity(Long id, String name) {
            this.id = id;
            this.name = name;
        }

        Long getId() { return id; }
        String getName() { return name; }
    }
}

import java.util.concurrent.Executor;
import org.springframework.aop.interceptor.AsyncUncaughtExceptionHandler;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.AsyncConfigurer;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

// Day la vi du DAY DU hon, THAY THE cho AsyncConfig don gian o vi du dau tien cua muc nay,
// khi ban can kiem soat executor va khong muon exception cua method @Async void bien mat.
@Configuration
@EnableAsync
class AsyncExecutorConfig implements AsyncConfigurer {

    // Boot co the auto-configure applicationTaskExecutor; cau hinh rieng khi can gioi han
    // so thread, hang doi va chinh sach qua tai theo dung nhu cau cua ung dung.
    @Override
    public Executor getAsyncExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setMaxPoolSize(8);
        executor.setQueueCapacity(100);
        executor.setThreadNamePrefix("app-async-");
        executor.initialize();
        return executor;
    }

    // Handler tuy chinh cho method @Async tra ve void: luong goi khong the nhan exception;
    // Spring mac dinh co log, con handler nay cho phep ghi/bao loi tap trung theo nhu cau.
    @Override
    public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() {
        return (throwable, method, params) ->
                System.err.println("Loi khong bat duoc trong @Async method " + method.getName() + ": " + throwable);
    }
}

import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Configuration
@EnableScheduling
class SchedulingConfig {
    // Bat co che @Scheduled cho toan bo application context.
}

@Component
class RecurringJobs {

    // Cho DU 5 phut ke tu khi LAN CHAY TRUOC KET THUC roi moi bat dau lan tiep theo -
    // an toan cho tac vu co thoi gian chay bien dong, khong bao gio chong lan.
    @Scheduled(fixedDelay = 5 * 60 * 1000)
    public void cleanupExpiredSessions() {
        // Trong ung dung that: xoa cac session/token da het han khoi store.
        System.out.println("cleanup expired sessions");
    }

    // Chay dung 0h00 moi ngay theo cron; KHAI BAO RO zone vi mac dinh dung timezone cua JVM,
    // thuong khac nhau giua may dev va container production.
    @Scheduled(cron = "0 0 0 * * *", zone = "Asia/Ho_Chi_Minh")
    public void generateDailyReport() {
        System.out.println("generate daily report");
    }
}

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
class InventorySyncJob {

    // spring.task.scheduling.pool.size=4 trong application.properties de scheduler co NHIEU
    // thread rieng - mac dinh Spring chi dung MOT thread cho TAT CA method @Scheduled, nen
    // mot job chay lau se lam tre moi job khac (xem bay dau tien trong vi du nay).
    @Scheduled(fixedRate = 60_000)
    public void syncInventory() {
        try {
            // ... cong viec co the nem exception, vi du goi mot service khac bi loi
            doSync();
        } catch (Exception ex) {
            // Ghi them context cua job (va trong app that: cap nhat metric/canh bao/retry co chu dich);
            // khong catch rong. Scheduler mac dinh van tiep tuc kich hoat cac lan chay sau.
            System.err.println("Loi khi syncInventory: " + ex.getMessage());
        }
    }

    private void doSync() {
        // Trong ung dung that: dong bo du lieu ton kho voi nguon ben ngoai.
    }
}

